package hexadecimal

// maxInt64 is the largest value that fits in an int64. It is defined
// explicitly (rather than imported from math) so that the conversion below
// is done purely from first principles, with no reliance on built-in or
// external libraries.
const maxInt64 = 9223372036854775807

// syntaxError is returned when the input is not a valid hexadecimal string.
type syntaxError struct {
	msg string
}

func (e *syntaxError) Error() string {
	return "syntax error: " + e.msg
}

// rangeError is returned when the value exceeds the range of int64.
type rangeError struct {
	msg string
}

func (e *rangeError) Error() string {
	return "range error: " + e.msg
}

// ParseHex converts a hexadecimal number, represented as a string
// (e.g. "10af8c"), to its decimal equivalent using first principles.
//
// It returns a syntax error when the input is empty or contains any
// character that is not a hexadecimal digit, and a range error when the
// resulting value does not fit in an int64.
func ParseHex(in string) (int64, error) {
	if in == "" {
		return 0, &syntaxError{"input is empty"}
	}

	var n int64
	for i := 0; i < len(in); i++ {
		c := in[i]

		var d int64
		switch {
		case c >= '0' && c <= '9':
			d = int64(c - '0')
		case c >= 'a' && c <= 'f':
			d = int64(c-'a') + 10
		case c >= 'A' && c <= 'F':
			d = int64(c-'A') + 10
		default:
			return 0, &syntaxError{"invalid character '" + string(c) + "' at position " + itoa(i)}
		}

		// Overflow check: ensure the next step, n*16 + d, does not exceed
		// maxInt64. All values here are non-negative, so integer division is
		// safe and the rearrangement n*16 + d > maxInt64  <=>  n > (maxInt64-d)/16
		// holds.
		if n > (maxInt64-d)/16 {
			return 0, &rangeError{"value exceeds the range of int64"}
		}
		n = n*16 + d
	}
	return n, nil
}

// HandleErrors takes a list of inputs for ParseHex and returns a matching list
// of error cases. It calls ParseHex on each input and, depending on the error
// result, puts one of "none", "syntax", or "range" in the result list.
func HandleErrors(inputs []string) []string {
	results := make([]string, len(inputs))
	for i, in := range inputs {
		_, err := ParseHex(in)
		switch err.(type) {
		case nil:
			results[i] = "none"
		case *rangeError:
			results[i] = "range"
		default:
			results[i] = "syntax"
		}
	}
	return results
}

// itoa converts a non-negative integer to its base-10 string form. It is a
// small first-principles helper used only to build error messages, so the
// conversion itself never depends on a formatting library.
func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	var b [24]byte
	i := len(b)
	for n > 0 {
		i--
		b[i] = byte('0' + n%10)
		n /= 10
	}
	return string(b[i:])
}

